using Microsoft.EntityFrameworkCore;
using SecureProxy.Domain.Entities;
using SecureProxy.Infrastructure.Persistence;
using Testcontainers.MsSql;

namespace SecureProxy.Tests.Integration;

// A real SQL Server in a throwaway Docker container, shared by the tests of one class.
// Needed because rowversion is generated by SQL Server itself; nothing in memory can fake it.
// Docker Desktop must be running.
public class SqlServerFixture : IAsyncLifetime
{
    private readonly MsSqlContainer _container = new MsSqlBuilder()
        .WithImage("mcr.microsoft.com/mssql/server:2022-latest")
        .Build();

    public async Task InitializeAsync()
    {
        // Pulls the image the first time (slow), then starts SQL Server (~10-30 seconds).
        await _container.StartAsync();

        // Same migrations as production create the tables.
        await using var db = CreateDbContext();
        await db.Database.MigrateAsync();
    }

    public Task DisposeAsync() => _container.DisposeAsync().AsTask();

    // Each call = a NEW DbContext, like a separate HTTP request or a separate admin.
    public ProxyDbContext CreateDbContext()
    {
        var options = new DbContextOptionsBuilder<ProxyDbContext>()
            .UseSqlServer(_container.GetConnectionString())
            .Options;
        return new ProxyDbContext(options);
    }

    // Adds a fresh destination + operation, and returns its id and current rowversion.
    // Every test calls this, so tests never touch each other's rows.
    public async Task<(int OperationId, byte[] RowVersion)> CreateOperationAsync()
    {
        await using var db = CreateDbContext();

        var operation = new Operation
        {
            Key = "test.op." + Guid.NewGuid().ToString("N"), // unique key per test
            HttpMethod = "GET",
            PathTemplate = "/items",
            IsActive = true,
            MaxRequestSizeBytes = 4096,
            Destination = new Destination
            {
                Name = "dest-" + Guid.NewGuid().ToString("N"),
                BaseUrl = "https://destination.test",
                IsActive = true,
                TimeoutSeconds = 5
            }
        };

        db.Operations.Add(operation);
        await db.SaveChangesAsync();

        return (operation.Id, operation.RowVersion);
    }
}
